import (
	"context"
	"fmt"
	"net/url"
	"sync"

	"go.flipt.io/flipt/internal/config"
	"go.opentelemetry.io/otel"
	otlpmetricgrpc "go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetricgrpc"
	otlpmetrichttp "go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetrichttp"
	"go.opentelemetry.io/otel/exporters/prometheus"
	"go.opentelemetry.io/otel/metric"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
)

// Meter is the default Flipt-wide otel metric Meter.
var Meter metric.Meter

func init() {
	// we do not create an exporter (e.g. Prometheus) here, as the exporter is
	// dependent on user configuration and can only be constructed once the
	// configuration has been loaded (see: GetExporter).
	// the global meter provider defers to a no-op provider until an exporter
	// has been configured, at which point any instruments created against this
	// meter are bound to the configured provider.
	Meter = otel.Meter("github.com/flipt-io/flipt")
}

var (
	metricExpOnce sync.Once
	metricExp     sdkmetric.Reader
	metricExpFunc func(context.Context) error = func(context.Context) error { return nil }
	metricExpErr  error
)

// GetExporter retrieves a configured sdkmetric.Reader based on the provided
// configuration. The reader is constructed once, any subsequent calls return
// the results of the initial construction.
func GetExporter(ctx context.Context, cfg *config.MetricsConfig) (sdkmetric.Reader, func(context.Context) error, error) {
	metricExpOnce.Do(func() {
		switch cfg.Exporter {
		case config.MetricsOTLP:
			u, err := url.Parse(cfg.OTLP.Endpoint)
			if err != nil {
				metricExpErr = fmt.Errorf("parsing otlp endpoint: %w", err)
				return
			}

			var reader sdkmetric.Reader
			switch u.Scheme {
			case "http", "https":
				opts := []otlpmetrichttp.Option{
					otlpmetrichttp.WithEndpoint(u.Host),
					otlpmetrichttp.WithHeaders(cfg.OTLP.Headers),
				}
				if u.Path != "" {
					opts = append(opts, otlpmetrichttp.WithURLPath(u.Path))
				}
				if u.Scheme == "http" {
					opts = append(opts, otlpmetrichttp.WithInsecure())
				}

				exp, err := otlpmetrichttp.New(ctx, opts...)
				if err != nil {
					metricExpErr = fmt.Errorf("creating otlp http metrics exporter: %w", err)
					return
				}

				reader = sdkmetric.NewPeriodicReader(exp)
			default:
				// the endpoint is either prefixed with the grpc scheme, or
				// provided as a bare host:port pair (i.e. no scheme).
				endpoint := cfg.OTLP.Endpoint
				if u.Scheme == "grpc" {
					endpoint = u.Host
				}

				opts := []otlpmetricgrpc.Option{
					otlpmetricgrpc.WithEndpoint(endpoint),
					otlpmetricgrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlpmetricgrpc.WithInsecure(),
				}

				exp, err := otlpmetricgrpc.New(ctx, opts...)
				if err != nil {
					metricExpErr = fmt.Errorf("creating otlp grpc metrics exporter: %w", err)
					return
				}

				reader = sdkmetric.NewPeriodicReader(exp)
			}

			metricExp = reader
			metricExpFunc = func(ctx context.Context) error {
				return reader.Shutdown(ctx)
			}
		case config.MetricsPrometheus:
			metricExp, metricExpErr = prometheus.New()
		default:
			metricExpErr = fmt.Errorf("unsupported metrics exporter: %s", cfg.Exporter)
		}
	})

	return metricExp, metricExpFunc, metricExpErr
}
