func TestTmpGetExporter(t *testing.T) {
	type args struct {
		name string
		cfg  *config.MetricsConfig
	}

	tests := []struct {
		name    string
		args    args
		subTest []struct {
			errAssert assert.ErrorAssertionFunc
		}
		wantErr bool
		errStr  string
	}{
		{
			name: "ok - prometheus",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsPrometheus,
				},
			},
			wantErr: false,
		},
		{
			name: "ok - otlp http",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsOTLP,
					OTLP: config.OTLPMetricsConfig{
						Endpoint: "http://localhost:4317",
						Headers:  map[string]string{"api-key": "test"},
					},
				},
			},
		},
		{
			name: "ok - otlp https",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsOTLP,
					OTLP: config.OTLPMetricsConfig{
						Endpoint: "https://localhost:4317",
					},
				},
			},
		},
		{
			name: "ok - otlp grpc",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsOTLP,
					OTLP: config.OTLPMetricsConfig{
						Endpoint: "grpc://localhost:4317",
					},
				},
			},
		},
		{
			name: "ok - otlp bare host",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsOTLP,
					OTLP: config.OTLPMetricsConfig{
						Endpoint: "localhost:4317",
					},
				},
			},
		},
		{
			name: "nok - unsupported",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled:  true,
					Exporter: config.MetricsExporter("unsupported"),
				},
			},
			wantErr: true,
			errStr:  "unsupported metrics exporter: unsupported",
		},
		{
			name: "nok - empty",
			args: args{
				cfg: &config.MetricsConfig{
					Enabled: true,
				},
			},
			wantErr: true,
			errStr:  "unsupported metrics exporter: ",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			metricExpOnce = sync.Once{}
			reader, fn, err := GetExporter(context.Background(), tt.args.cfg)
			if tt.wantErr {
				require.Error(t, err)
				assert.Equal(t, tt.errStr, err.Error())
				return
			}
			require.NoError(t, err)
			assert.NotNil(t, reader)
			assert.NotNil(t, fn)
			assert.NoError(t, fn(context.Background()))
		})
	}
}
"}

